describe('Notification Empty State', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display empty state when no notifications are present', () => {
    // Verify notification container exists
    cy.get('[data-testid="notification-container"]').should('be.visible');

    // Verify empty state message is visible
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No new notifications');

    // Verify no notification items are displayed
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Verify empty state styling is applied
    cy.get('[data-testid="notification-container"]').should('have.class', 'empty-state');
  });

  it('should handle empty state when notifications are cleared', () => {
    // Verify initial empty state is displayed
    cy.get('[data-testid="notification-container"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No new notifications');

    // Verify empty state styling is applied
    cy.get('[data-testid="notification-container"]').should('have.class', 'empty-state');

    // Clear notifications
    cy.get('[data-testid="clear-notifications-button"]').click();

    // Verify empty state persists after clearing
    cy.get('[data-testid="notification-container"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No new notifications');

    // Verify empty state styling is still applied
    cy.get('[data-testid="notification-container"]').should('have.class', 'empty-state');
  });
});
